PYTHONIOENCODING=utf-8 py -V:3.12 -I -B -c "import json,pathlib; base=pathlib.Path('scratch');
for task,n in [('t27','cursor_t22.json'),('t30','cursor_clhs.json'),('t31','cursor_csrs.json'),('t32','cursor_cmti.json'),('t34','cursor_cntp.json'),('t36','cursor_cdbt.json')]:
 d=json.loads((base/task/'out'/n).read_text(encoding='utf-8')); print('\\n',task,n,'keys',list(d));
 for k,v in d.items():
  if any(t in k.lower() for t in ['layout','closure','sha','payload','count','stride','archive','table','footer','header','row']): print(k, json.dumps(v,ensure_ascii=False)[:900])"

PYTHONIOENCODING=utf-8 py -V:3.12 -I -B -c "import json,pathlib,glob; base=pathlib.Path('scratch');
for task,code in [('t27','t22'),('t30','clhs'),('t31','csrs'),('t32','cmti'),('t34','cntp'),('t36','cdbt')]:
 root=base/task/'out'; files=sorted(root.glob('instructions.part*.json')); mp={}
 for p in files:
  for x in json.loads(p.read_text(encoding='utf-8')).get('instructions',[]):
   try: mp[int(x['file_offset'],0)]=(x.get('VA'),x.get('instruction'))
   except: pass
 d=json.loads((root/f'fields_{code}.json').read_text(encoding='utf-8')); print('\\n',task,'instruction_count',len(mp))
 for f in d.get('fields',[]):
  ss=f.get('candidate_sink') or f.get('sink') or f.get('sinks') or []
  if isinstance(ss,dict):ss=[ss]
  for s in ss:
   z=s.get('reader_site',s.get('site'))
   if z is not None: print(f.get('code'),hex(z) if isinstance(z,int) else z,mp.get(z))
"

PYTHONIOENCODING=utf-8 py -V:3.12 -I -B -c "import json,pathlib; root=pathlib.Path('scratch/t27/out'); d=json.loads((root/'fields_t22.json').read_text(encoding='utf-8'));
for part in d['fields']:
 x=json.loads((root/part).read_text(encoding='utf-8'))
 for f in x['fields']:
  if f.get('candidate_code') or f.get('code'):
   print(json.dumps({k:f.get(k) for k in ['code','candidate_code','name','grade','row_offset','wire_offset','width','object_off','VA','file_offset','disposition','schema_occurrences','t20_linear_candidate']},ensure_ascii=False)[:900])
   print('GETTER',json.dumps(f.get('getter'),ensure_ascii=False)[:450])"

