 d=json.loads((base/task/'out'/n).read_text(encoding='utf-8')); a=d['archives'][arc]; print('\\n',task, 'top', list(a));
 print(json.dumps({k:a.get(k) for k in ['present','payload_len','payload_sha256','row_count','stride','header_hex','header_size','wire_row_origin','legacy_row_origin','footer','footer_hex','closure','row_size','body_size','profile']},ensure_ascii=False)[:2600])
 if task=='t27':pass
"

PYTHONIOENCODING=utf-8 py -V:3.12 -I -B -c "import json,pathlib; base=pathlib.Path('scratch');
for task,code in [('t30','clhs'),('t31','csrs'),('t32','cmti'),('t34','cntp'),('t36','cdbt')]:
 root=base/task/'out'; mp={}
 for p in sorted(root.glob('instructions.part*.json')):
  for x in json.loads(p.read_text(encoding='utf-8')).get('instructions',[]):
   try: mp[int(x['file_offset'],0)]=x.get('VA')
   except (ValueError,TypeError): pass
 d=json.loads((root/f'fields_{code}.json').read_text(encoding='utf-8')); print('\\n',task,'instructions',len(mp))
 for f in d.get('fields',[]):
  if f.get('grade')=='L3_named_row_coordinate' or f.get('grade')=='L3_contextual_row_coordinates':
   ss=f.get('candidate_sink') or f.get('sink') or f.get('sinks') or []
   if isinstance(ss,dict):ss=[ss]
   sites=[]
   for s in ss:
    z=s.get('reader_site',s.get('site')); sites.append((z,mp.get(z) if isinstance(z,int) else None))
   g=f.get('getter',{}); ac=g.get('access',g.get('arm',g.get('load'))); gl=mp.get(ac) if isinstance(ac,int) else None
   print(f.get('code'), 'row',f.get('row_offset'),'sink',sites,'getter',ac,gl)"

